/* ---------- Cap Cup prices (made up, like fantasy sports salaries) ---------- */
/* Every player gets a price in $M from his rating. The curve is steep at the top, so stars cost a lot and depth players are cheap.
   Goalies and centers cost a bit more and defensemen a bit less, because they count for more or less of team rating. Not real salaries. */
const CAP_CUP = {
  CAP: 28,                                   // salary cap for the six-player lineup, in $M. Raised from 26 to 28 on Oct 10, 2026 (Daniel): smart bot beats a typical opponent ~40%.
  POS_MULT: { G: 1.25, C: 1.1, LW: 1, RW: 1, D: 0.85 },
  BASE: 0.7, SPAN: 11.3, LOW: 63, HIGH: 104, CURVE: 2.2
};
function priceFor(pos, rating) {
  const t = Math.max(0, Math.min(1, (rating - CAP_CUP.LOW) / (CAP_CUP.HIGH - CAP_CUP.LOW)));
  return Math.round((CAP_CUP.BASE + Math.pow(t, CAP_CUP.CURVE) * CAP_CUP.SPAN) * CAP_CUP.POS_MULT[pos] * 10) / 10;
}

const ROSTERS = RAW_ROSTERS.map(r => {
  const key = r.fr + "-" + r.decade;
  if (!ROSTER_CONF[key]) throw new Error("No conference set for roster " + key);
  return {
    key, fr: r.fr, decade: r.decade, conf: ROSTER_CONF[key],
    players: r.players.map((s, i) => {
      const [name, pos, rating, num, line] = s.split("|");
      return { id: key + ":" + i, name, pos, rating: +rating, number: num ? +num : null, line: line || "", price: priceFor(pos, +rating), rosterKey: key };
    })
  };
});
const ROSTER_BY_KEY = Object.fromEntries(ROSTERS.map(r => [r.key, r]));
/* What to keep in reserve for each open slot. Not the single cheapest player in the game (that would force a hunt for one exact player),
   but a price that at least 40% of rosters can beat with someone eligible for that slot, so a fitting player turns up within a spin or two. */
const MIN_PRICE = (() => {
  const groups = { W: ["LW", "RW"], C: ["C"], D: ["D"], G: ["G"] }, out = {};
  for (const g in groups) {
    const perRoster = ROSTERS.map(r => Math.min(99, ...r.players.filter(p => groups[g].includes(p.pos)).map(p => p.price))).sort((x, y) => x - y);
    const v = perRoster[Math.floor(perRoster.length * 0.4)];
    for (const pos of groups[g]) out[pos] = v;
  }
  return out;
})();

