/* ---------- Random helpers (seedable so tests are repeatable) ---------- */
function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
function randInt(rng, n) { return Math.floor(rng() * n); }
function pick(rng, arr) { return arr[randInt(rng, arr.length)]; }
function shuffle(rng, arr) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) { const j = randInt(rng, i + 1); [a[i], a[j]] = [a[j], a[i]]; }
  return a;
}
function gauss(rng) {
  let u = 0, v = 0;
  while (u === 0) u = rng();
  while (v === 0) v = rng();
  return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
}

/* ---------- Draft rules ---------- */
/* State: { picks: {slotId: player}, used: {decade:false, franchise:false},
            current: rosterKey|null, rerolledThisSpin: bool, seen: [rosterKeys] } */
function newDraft(opts) {
  return { picks: {}, used: { decade: false, franchise: false }, current: null, rerolledThisSpin: false, seen: [], capOnly: !!(opts && opts.cap) };
}
function openSlots(d) { return SLOTS.filter(s => !d.picks[s.id]); }
function picksCount(d) { return Object.keys(d.picks).length; }
function isDraftComplete(d) { return picksCount(d) === SLOTS.length; }

/* Any roster can come up again. That is what makes real-linemate bonuses possible: two players from the same roster. */
function availableRosters(d) { return ROSTERS; }

/* A fresh spin: pick a decade at random, then a franchise from that decade. */
function spin(d, rng) {
  const pool = availableRosters(d);
  const decades = [...new Set(pool.map(r => r.decade))];
  const decade = pick(rng, decades);
  const r = pick(rng, pool.filter(x => x.decade === decade));
  d.current = r.key;
  d.rerolledThisSpin = false;
  d.seen.push(r.key);
  return r;
}

/* Which rosters could a re-roll land on? decade re-roll keeps the franchise; franchise re-roll keeps the decade. */
function rerollOptions(d, kind) {
  if (!d.current) return [];
  const cur = ROSTER_BY_KEY[d.current];
  // Cap Cup: a re-roll only lands on a roster where someone still fits under the cap, so it never turns into a surprise free re-spin of both reels
  const pool = availableRosters(d).filter(r => r.key !== cur.key && (!d.capOnly || anyAffordable(d, r.key)));
  const normal = kind === "decade"
    ? pool.filter(r => r.fr === cur.fr)
    : pool.filter(r => r.decade === cur.decade);
  if (normal.length) return normal;
  // Oct 12, 2026: a franchise that only existed in one decade (e.g. 1970s California Golden Seals) has nowhere
  // for a decade re-roll to go, so the re-roll becomes a full re-spin: new decade and new franchise.
  return pool.filter(r => r.fr !== cur.fr && r.decade !== cur.decade);
}
/* True when this re-roll can't keep the other reel and will re-spin both instead. */
function rerollIsFull(d, kind) {
  if (!d.current) return false;
  const cur = ROSTER_BY_KEY[d.current];
  const opts = rerollOptions(d, kind);
  return opts.length > 0 && opts.every(r => kind === "decade" ? r.fr !== cur.fr : r.decade !== cur.decade);
}
function canReroll(d, kind) {
  if (d.used[kind]) return false;
  if (CONFIG.ONE_REROLL_PER_SPIN && d.rerolledThisSpin) return false;
  return rerollOptions(d, kind).length > 0;
}
function reroll(d, kind, rng) {
  if (!canReroll(d, kind)) return null;
  const r = pick(rng, rerollOptions(d, kind));
  d.used[kind] = true;
  d.rerolledThisSpin = true;
  d.current = r.key;
  d.seen.push(r.key);
  return r;
}

/* Can this player fill this slot? Wingers (LW or RW) can play either wing. */
function eligible(slot, player) {
  if (slot.pos === "LW" || slot.pos === "RW") return player.pos === "LW" || player.pos === "RW";
  return slot.pos === player.pos;
}
/* Which slot would a player fill? Natural side first, otherwise the other wing. Returns slot id or null. */
function isDrafted(d, player) { return Object.values(d.picks).some(p => p.name === player.name); }
function slotFor(d, player) {
  if (isDrafted(d, player)) return null;
  const open = openSlots(d).filter(s => eligible(s, player));
  if (!open.length) return null;
  const natural = open.find(s => s.pos === player.pos);
  return (natural || open[0]).id;
}
/* Every open slot this player could fill (a winger with both wing slots open gets two choices). */
function slotOptions(d, player) {
  if (isDrafted(d, player)) return [];
  return openSlots(d).filter(s => eligible(s, player)).map(s => s.id);
}
/* Draft a player. Pass slotId to choose the slot (e.g. LW or RW); otherwise the natural slot is used. */
function draftPlayer(d, player, slotId) {
  const slot = slotId || slotFor(d, player);
  if (!slot || !slotOptions(d, player).includes(slot)) return false;
  d.picks[slot] = player;
  d.current = null;
  return true;
}

/* ---------- Ratings & season sim ---------- */
const F_IDS = ["LW", "C", "RW"], D_IDS = ["D1", "D2"];
const slotWeight = id => SLOTS.find(s => s.id === id).weight;

function baseRating(picks) {
  let total = 0;
  for (const s of SLOTS) total += (picks[s.id] ? picks[s.id].rating : 0) * s.weight;
  return total;
}

/* Work out which bonuses a lineup has earned. Each item: { kind: "F"|"D"|"ALL", type: "conf"|"o6"|"chic", ids: [slot ids], label, detail, points, rating }.
   kind says where the badge shows on the board: under the forward line, under the defense pair, or lineup-wide. */
function lineItems(picks) {
  const items = [];
  const frOf = p => (p && p.rosterKey ? ROSTER_BY_KEY[p.rosterKey].fr : null);

  // Conference Bonus: each full line on its own
  for (const [kind, ids] of [["F", F_IDS], ["D", D_IDS]]) {
    if (!ids.every(id => picks[id] && picks[id].rosterKey)) continue;
    const confs = ids.map(id => confOf(picks[id].rosterKey));
    if (confs.every(c => c === confs[0])) {
      items.push({ kind, type: "conf", ids: ids.slice(), label: CONF_NAME[confs[0]] + " Conference Bonus - +" + BONUS.CONF, detail: (kind === "F" ? "Forwards" : "Defense") + " all " + CONF_NAME[confs[0]], points: BONUS.CONF, rating: 0 });
    }
  }

  // Original Six Bonus: all six players
  const allIds = SLOTS.map(s => s.id);
  if (allIds.every(id => picks[id] && frOf(picks[id]) && isO6(frOf(picks[id])))) {
    items.push({ kind: "ALL", type: "o6", ids: allIds, label: "Original Six Bonus - +" + BONUS.O6, detail: "All six from Original Six teams", points: BONUS.O6, rating: 0 });
  }

  // Chiclets Bonus: all three on the lineup
  const chicIds = CHICLETS.map(n => allIds.find(id => picks[id] && picks[id].name === n));
  if (chicIds.every(Boolean)) {
    items.push({ kind: "ALL", type: "chic", ids: chicIds, label: "Chiclets Bonus", detail: "Biz, Whitney and Yandle together", points: BONUS.CHICLETS, rating: 0 });
  }
  return items;
}

/* Apply the bonuses with the 99 cap. Fills in each item's team-rating value; returns the overall each slot actually gained. */
function applyBonuses(picks, items) {
  const cur = {}, start = {};
  for (const s of SLOTS) if (picks[s.id]) { cur[s.id] = picks[s.id].rating; start[s.id] = cur[s.id]; }
  for (const it of items) {
    let w = 0;
    for (const id of it.ids) {
      const next = Math.min(CAP, cur[id] + it.points);
      w += (next - cur[id]) * slotWeight(id);
      cur[id] = next;
    }
    it.rating = w;
  }
  const gains = {};
  for (const id in cur) gains[id] = cur[id] - start[id];
  return gains;
}

/* Overall boost each drafted player actually gets, by slot id. */
function slotBoosts(picks) {
  return applyBonuses(picks, lineItems(picks));
}

function ratingBreakdown(picks) {
  const base = baseRating(picks);
  const items = lineItems(picks);
  applyBonuses(picks, items);
  const bonus = items.reduce((a, i) => a + i.rating, 0);
  return { base, bonus, total: base + bonus, items };
}
function lineupRating(picks) { return ratingBreakdown(picks).total; }

/* Live preview: what would drafting this player into slotId add? */
function bonusPreview(d, player, slotId) {
  const before = ratingBreakdown(d.picks);
  const after = ratingBreakdown(Object.assign({}, d.picks, { [slotId]: player }));
  const keyOf = i => i.kind + "|" + i.type + "|" + i.label;
  const had = new Set(before.items.map(keyOf));
  return { delta: after.bonus - before.bonus, newItems: after.items.filter(i => !had.has(keyOf(i))), after };
}


/* Chance the drafted team beats one opponent. */
function winProb(mine, opp) {
  return 1 / (1 + Math.exp(-(mine - opp) / CONFIG.SCALE));
}

function simulateSeason(rating, rng) {
  // Build the 31-team league for this season, each with its own strength
  const league = OPPONENTS.slice(0, 31).map(name => ({
    name, rating: Math.max(60, Math.min(96, CONFIG.OPP_MEAN + gauss(rng) * CONFIG.OPP_SD))
  }));
  // Schedule: cycle through a shuffled league until we have enough games
  const sched = [];
  while (sched.length < CONFIG.GAMES) sched.push(...shuffle(rng, league));
  sched.length = CONFIG.GAMES;

  const games = sched.map((opp, i) => {
    const p = winProb(rating, opp.rating);
    return { n: i + 1, opp: opp.name, oppRating: opp.rating, p, win: rng() < p };
  });
  let wins = 0, streak = 0, best = 0;
  for (const g of games) {
    if (g.win) { wins++; streak++; best = Math.max(best, streak); } else streak = 0;
  }
  return { games, wins, losses: CONFIG.GAMES - wins, bestStreak: best, perfect: wins === CONFIG.GAMES };
}

/* Result tiers, from wins */
function tierFor(wins) {
  if (wins === CONFIG.GAMES) return { name: "Perfect Season", note: "84-0. Flawless, start to finish." };
  if (wins >= 76) return { name: "Untouchable", note: "One of the greatest teams ever assembled." };
  if (wins >= 66) return { name: "All-Time Great", note: "A dynasty on skates." };
  if (wins >= 56) return { name: "Powerhouse", note: "Cup favorite from opening night." };
  if (wins >= 46) return { name: "Contender", note: "A real playoff threat." };
  if (wins >= 36) return { name: "Bubble Team", note: "Fighting for a wild card." };
  return { name: "Lottery Pick", note: "Better luck with the next draft." };
}

/* ---------- Game modes ---------- */
/* classic: the game with ratings shown.  iq: names only, no ratings, so the player must know the game.  cap: every player has a price and the lineup must fit under the cap. */
const MODES = {
  classic: { key: "classic", label: "Classic", index: 0 },
  iq:      { key: "iq",      label: "ICE-IQ", index: 1, noise: 5 },   // simulated players see ratings with noise, like fans judging by name
  cap:     { key: "cap",     label: "Cap Cup", index: 2 }
};

/* ---------- Cap Cup rules ---------- */
const spentOf = d => Object.values(d.picks).reduce((a, p) => a + p.price, 0);
const capLeft = d => CAP_CUP.CAP - spentOf(d);
/* what the other open slots would need at the very least, if this pick fills slotId */
function reserveFor(d, slotId) {
  let r = 0;
  for (const sl of openSlots(d)) if (sl.id !== slotId) r += MIN_PRICE[sl.pos];
  return r;
}
/* can this player go in this slot without making it impossible to finish the lineup under the cap? */
function capOK(d, player, slotId) {
  return spentOf(d) + player.price + reserveFor(d, slotId) <= CAP_CUP.CAP + 1e-9;
}
/* the slots this player could fill and afford */
function capOptions(d, player) { return slotOptions(d, player).filter(id => capOK(d, player, id)); }
/* does anyone on this roster fit? if not, the app gives a free re-spin */
function anyAffordable(d, rosterKey) { return ROSTER_BY_KEY[rosterKey].players.some(p => capOptions(d, p).length > 0); }

/* ---------- Cap Cup head-to-head: the ten best regular seasons in NHL history ---------- */
/* The ten best points percentages (points / (2 x games)), as listed by StatMuse and NHL Records. Each opponent shows its first forward line,
   its first defense pair and its goalie, for looks only: they are not rated and do not play. To beat one, your 84-game season needs more wins
   than the opponent's win rate scaled to 84 games (wins / games x 84). w-l-t: t is ties or overtime losses, whichever the era used.
   The lines are a best reading of each season's regular lineup and can be corrected by name; the records are exact. */
const RECORD_TEAMS = [
  /* The ten winningest regular seasons in NHL history (most wins, per NHL.com, set Oct 10, 2026 by Daniel). w-l-t: t is ties or
     overtime losses, whichever the era used. Lines are a best reading of each team's regular lineup, for looks only. */
  { id: "BOS-2022", season: "2022–23", fr: "BOS", w: 65, l: 12, t: 5,  lineup: { LW: "Brad Marchand",     C: "Patrice Bergeron", RW: "David Pastrnak",  D1: "Hampus Lindholm",  D2: "Charlie McAvoy",        G: "Linus Ullmark" } },
  { id: "DET-1995", season: "1995–96", fr: "DET", w: 62, l: 13, t: 7,  lineup: { LW: "Vyacheslav Kozlov", C: "Steve Yzerman",    RW: "Sergei Fedorov",  D1: "Nicklas Lidstrom", D2: "Vladimir Konstantinov", G: "Chris Osgood" } },
  { id: "TBL-2018", season: "2018–19", fr: "TBL", w: 62, l: 16, t: 4,  lineup: { LW: "Ondrej Palat",      C: "Brayden Point",    RW: "Nikita Kucherov", D1: "Victor Hedman",    D2: "Ryan McDonagh",         G: "Andrei Vasilevskiy" } },
  { id: "MTL-1976", season: "1976–77", fr: "MTL", w: 60, l: 8,  t: 12, lineup: { LW: "Steve Shutt",       C: "Jacques Lemaire",  RW: "Guy Lafleur",     D1: "Larry Robinson",   D2: "Serge Savard",          G: "Ken Dryden" } },
  { id: "MTL-1977", season: "1977–78", fr: "MTL", w: 59, l: 10, t: 11, lineup: { LW: "Steve Shutt",       C: "Jacques Lemaire",  RW: "Guy Lafleur",     D1: "Larry Robinson",   D2: "Serge Savard",          G: "Ken Dryden" } },
  { id: "MTL-1975", season: "1975–76", fr: "MTL", w: 58, l: 11, t: 11, lineup: { LW: "Steve Shutt",       C: "Jacques Lemaire",  RW: "Guy Lafleur",     D1: "Larry Robinson",   D2: "Serge Savard",          G: "Ken Dryden" } },
  { id: "DET-2005", season: "2005–06", fr: "DET", w: 58, l: 16, t: 8,  lineup: { LW: "Henrik Zetterberg", C: "Pavel Datsyuk",    RW: "Tomas Holmstrom", D1: "Nicklas Lidstrom", D2: "Mathieu Schneider",     G: "Manny Legace" } },
  { id: "FLA-2021", season: "2021–22", fr: "FLA", w: 58, l: 18, t: 6,  lineup: { LW: "Jonathan Huberdeau", C: "Aleksander Barkov", RW: "Sam Reinhart",   D1: "Aaron Ekblad",     D2: "MacKenzie Weegar",      G: "Sergei Bobrovsky" } },
  { id: "BOS-1970", season: "1970–71", fr: "BOS", w: 57, l: 14, t: 7,  lineup: { LW: "Wayne Cashman",     C: "Phil Esposito",    RW: "Ken Hodge",       D1: "Bobby Orr",        D2: "Dallas Smith",          G: "Gerry Cheevers" } },
  { id: "EDM-1983", season: "1983–84", fr: "EDM", w: 57, l: 18, t: 5,  lineup: { LW: "Glenn Anderson",    C: "Wayne Gretzky",    RW: "Jari Kurri",      D1: "Paul Coffey",      D2: "Kevin Lowe",            G: "Grant Fuhr" } }
].map(t => {
  const gp = t.w + t.l + t.t, pts = 2 * t.w + t.t, pace = t.w / gp * CONFIG.GAMES;
  const fr = t.fr ? FRANCHISES[t.fr] : null;
  return Object.assign({}, t, {
    team: t.team || fr.name,
    colors: t.colors || { c1: fr.c1, c2: fr.c2 },
    gp, pts, ptsPct: pts / (2 * gp),
    pace,                                        // their wins, scaled to an 84-game season
    need: Math.floor(pace + 1e-9) + 1            // the fewest wins that beat that pace
  });
});
const pickRecordTeam = rng => RECORD_TEAMS[randInt(rng, RECORD_TEAMS.length)];
const beatsRecord = (t, wins) => wins > t.pace + 1e-9;

/* ---------- Simulated field: the rank and percentile card ---------- */
/* Until real players exist, "today's teams" are simulated bot drafters: a mix of always-take-the-best and smarter ones that also
   spend a re-roll when the best option is weak. Seeded by the date and the mode so everyone sees the same field on the same day.
   ICE-Q bots see each player's rating with some noise, so the IQ field is weaker than the Classic one.
   Cap Cup bots must stay under the cap: the simple ones take the best player they can afford, the smart ones spread money across spots.
   Ranking is by season record, with team rating as the tiebreaker. */
function botDraft(rng, smart, opts) {
  opts = opts || {};
  const noise = opts.noise || 0, cap = !!opts.cap;
  const d = newDraft({ cap });
  const seen = new Map();
  const perceived = p => {
    if (!noise) return p.rating;
    if (!seen.has(p.id)) seen.set(p.id, p.rating + gauss(rng) * noise);
    return seen.get(p.id);
  };
  const bestOf = () => {
    let cands = [];
    for (const p of ROSTER_BY_KEY[d.current].players) {
      const slot = slotFor(d, p); if (!slot) continue;
      if (cap && !capOK(d, p, slot)) continue;
      cands.push({ p, slot, v: perceived(p) * slotWeight(slot) });
    }
    if (cap && smart && cands.length) {
      const share = capLeft(d) / openSlots(d).length;   // an even share of the money left
      const modest = cands.filter(c => c.p.price <= share * 1.35);
      if (modest.length) cands = modest;
    }
    let best = null;
    for (const c of cands) if (!best || c.v > best.v) best = c;
    return best ? best.p : null;
  };
  const threshold = cap ? 80 : 88;
  let guard = 0;
  while (!isDraftComplete(d) && guard++ < 200) {
    spin(d, rng);
    let p = bestOf();
    if (!p) continue;   // nobody on this roster fits the cap: free re-spin
    if (smart && perceived(p) < threshold) {
      for (const kind of ["decade", "franchise"]) if (canReroll(d, kind)) { const q = reroll(d, kind, rng); const p2 = q ? bestOf() : null; if (p2) p = p2; break; }
    }
    draftPlayer(d, p);
  }
  return d.picks;
}
function buildField(seed, n, mode) {
  const m = MODES[mode || "classic"];
  const rng = mulberry32(seed * 10 + m.index), out = [];
  const opts = { noise: m.noise || 0, cap: m.key === "cap" };
  for (let i = 0; i < n; i++) {
    const picks = botDraft(rng, i % 5 < 2 || (opts.cap && i % 5 < 3), opts);
    const rating = lineupRating(picks);
    const wins = simulateSeason(rating, rng).wins;
    out.push({ name: "sim-" + String(i + 1).padStart(4, "0"), wins, losses: CONFIG.GAMES - wins, rating, picks });
  }
  return out;
}
/* Leaderboard order: better record first, higher team rating breaks a tie. */
const outranks = (a, b) => a.wins > b.wins || (a.wins === b.wins && a.rating > b.rating);
/* The whole board, best first, with ranks. Pass the player's own posted entry to put it in the right place (flagged isMe). */
function leaderboard(field, entry) {
  const all = field.slice();
  if (entry) all.push(Object.assign({}, entry, { isMe: true }));
  all.sort((a, b) => outranks(a, b) ? -1 : outranks(b, a) ? 1 : 0);
  // Teams with the same record and the same rating share a rank (standard competition ranking: 1, 2, 2, 4).
  const out = [];
  all.forEach((t, i) => out.push(Object.assign({}, t, { rank: i > 0 && !outranks(all[i - 1], t) ? out[i - 1].rank : i + 1 })));
  return out;
}
/* Where a finished season lands in the field. rank 1 is best. beatsPct is the share of the field this team finished ahead of. */
function rankAgainst(field, wins, rating) {
  let better = 0, beaten = 0;
  for (const t of field) {
    if (outranks(t, { wins, rating })) better++; else beaten++;
  }
  return { rank: better + 1, total: field.length + 1, beatsPct: beaten / field.length * 100 };
}

/* ---------- Display-name filter ---------- */
/* Blocks offensive display names before they can be posted. It is a first line of defense, not a guarantee: it catches common
   profanity and slurs, including disguised versions (numbers for letters, stretched letters, dots or dashes between letters,
   single letters spaced out like "f u c k"). It is careful with real hockey names: Nazem, Dickinson, Hitchcock, Hancock, Cockburn
   all pass, and "Pass Hit" is not read as a swear word. Word lists are lowercase. A term matches with any letter stretched:
   "fuuuck" matches "fuck", but a doubled letter in the term ("ass") must stay doubled, so the ordinary word "as" is fine. */
const NAME_BLOCK_ANYWHERE = [   // blocked when they appear inside any word of the name
  "fuck", "shit", "bitch", "cunt", "nigg", "fagg", "retard", "whore", "bastard", "asshole", "dickhead", "cocksuck", "jizz",
  "dildo", "rapist", "molest", "pedophile", "porn", "hitler", "kkk", "tranny", "wetback", "killyourself"
];
const NAME_BLOCK_WORDS = [      // blocked only as a whole word, because they sit inside innocent words and names
  "ass", "arse", "cock", "dick", "pussy", "cum", "sex", "tits", "boob", "boobs", "anal", "anus", "penis", "vagina", "rape",
  "slut", "fag", "fags", "dyke", "kike", "spic", "gook", "coon", "chink", "paki", "nazi", "pedo", "kys", "twat", "wank",
  "piss", "milf", "tard", "sperm", "negro", "nig", "homo", "hoe", "hoes"
];
const NAME_BLOCK_PHRASES = ["killyourself", "killurself", "hangyourself"];   // checked with every space and symbol removed
const NAME_RESERVED = ["admin", "administrator", "moderator", "mod", "staff", "support", "official", "chel840", "chel84"];
const LEET = { "0": "o", "1": "i", "3": "e", "4": "a", "5": "s", "7": "t", "@": "a", "$": "s", "!": "i", "+": "t" };
function termRegex(term, anchored) {
  const runs = term.match(/(.)\1*/g).map(r => r[0] + "{" + r.length + ",}").join("");
  return new RegExp(anchored ? "^" + runs + "$" : runs);
}
const NAME_ANY_RX = NAME_BLOCK_ANYWHERE.map(t => termRegex(t, false));
const NAME_WORD_RX = NAME_BLOCK_WORDS.map(t => termRegex(t, true));

/* Returns "" if the name is fine, otherwise a message for the player. */
function nameProblem(raw) {
  const name = String(raw).replace(/\s+/g, " ").trim();
  if (name.length < 3 || name.length > 20 || !/^[A-Za-z0-9 _.\-]+$/.test(name)) return "Use 3 to 20 letters, numbers, spaces, dots, dashes or underscores.";
  if (/^sim-\d+$/i.test(name)) return "That name is reserved for the simulated teams. Try another.";
  const lower = name.toLowerCase().replace(/[013457]/g, c => LEET[c]);
  // words as typed (dots, dashes and underscores split words), and a version where they are removed so "f.u.c.k" and "sh_it" read as one word
  const split = lower.split(/[^a-z]+/).filter(Boolean);
  const joined = lower.replace(/[._\-]/g, "").split(/ +/).filter(Boolean);
  // a run of single letters ("f u c k", "f.u.c.k") counts as one word
  const merged = [];
  let run = "";
  for (const w of split.concat("")) {
    if (w.length === 1) { run += w; continue; }
    if (run.length > 1) merged.push(run);
    run = "";
    if (w) merged.push(w);
  }
  const words = merged.concat(joined);
  const plain = name.toLowerCase();   // reserved names are compared before numbers are read as letters, so "chel840" is caught
  const plainWords = plain.split(/[ ._\-]+/).concat(plain.replace(/[ ._\-]/g, ""));
  if (plainWords.some(w => NAME_RESERVED.includes(w))) return "That name is reserved. Try another.";
  if (NAME_BLOCK_PHRASES.some(t => lower.replace(/[^a-z]/g, "").includes(t))) return "That name isn't allowed. Try a different one.";
  if (words.some(w => NAME_ANY_RX.some(r => r.test(w)) || NAME_WORD_RX.some(r => r.test(w)))) return "That name isn't allowed. Try a different one.";
  return "";
}

